window.products.push({"id":505643,"name":"Wilton Candy Melts Melting Pot","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/61mCUDuAjnL._AC_SL1500_.jpg","description":"Easily melt up to two and a half cups of Candy Melts candy for dipped strawberries, pretzels, bark candy and more in the Wilton Deluxe Melting Pot. With two temperature settings, it's easy to melt the candy and then keep it at a consistent temperature while you dip your sweet treats. Once you've finished making your treats, simply chill the silicone pot until the candy hardens, then gently squeeze the soft silicone pot to break up the candy a bit and it comes right out, making cleanup easy!","images":["https://m.media-amazon.com/images/I/61mCUDuAjnL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Wilton","source_asin":"B013PQJ57E","category_path":"Home & Kitchen"},"sku":"BM-505643","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B013PQJ57E","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B013PQJ57E","price_pending":true,"merchant_ready":false});
